  /**
   * Get global chat prompts
   */
  async getGlobalPrompts(userId: string): Promise<any> {
    const response = await apiClient.get(`/api/prompts/global?user_id=${userId}`)
    return response.data
  },

  /**
   * Bulk upload multiple documents
   */
  async bulkUpload(request: BatchUploadRequest): Promise<BatchUploadResponse> {
    const formData = new FormData()

    // Append all files
    request.files.forEach((file) => {
      formData.append('files', file)
    })

    // Append optional metadata
    if (request.title_prefix) {
      formData.append('title_prefix', request.title_prefix)
    }
    if (request.subject) {
      formData.append('subject', request.subject)
    }
    if (request.tags) {
      formData.append('tags', request.tags)
    }

    const response = await apiClient.post<BatchUploadResponse>(
      '/api/documents/bulk-upload',
      formData,
      {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
        timeout: 600000, // 10 minute timeout for bulk uploads
      }
    )

    return response.data
  },

  /**
   * Get batch upload status
   */
  async getBatchStatus(batchId: string): Promise<BatchStatusResponse> {
    const response = await apiClient.get<BatchStatusResponse>(
      `/api/documents/batch/${batchId}`
    )
    return response.data
  },
}

