/**
 * BatchUploadProgress Component
 * Displays real-time progress for batch document uploads
 */

import { useEffect, useState, useRef } from 'react'
import { Progress } from '../../../components/ui/progress'
import { Badge } from '../../../components/ui/Badge'
import { ScrollArea } from '../../../components/ui/scroll-area'
import { Alert, AlertDescription } from '../../../components/ui/alert'
import {
  CheckCircle,
  XCircle,
  Loader2,
  Clock,
  FileText,
  Copy,
  AlertTriangle,
} from 'lucide-react'
import type { BatchFileStatus, BatchWebSocketEvent } from '../../../api/types'
import { documentsService } from '../../../api/documents.service'

interface BatchUploadProgressProps {
  batchId: string
  totalFiles: number
  initialFiles: Array<{
    filename: string
    size_mb: number
    status: string
  }>
  onComplete?: (results: {
    completedFiles: number
    failedFiles: number
    files: BatchFileStatus[]
  }) => void
}

export function BatchUploadProgress({
  batchId,
  totalFiles,
  initialFiles,
  onComplete,
}: BatchUploadProgressProps) {
  const [files, setFiles] = useState<BatchFileStatus[]>(
    initialFiles.map((f, idx) => ({
      filename: f.filename,
      file_index: idx,
      status: f.status as 'pending' | 'processing' | 'completed' | 'failed',
      is_duplicate: false,
      total_chunks: 0,
      processed_chunks: 0,
      progress: 0,
    }))
  )
  const [completedFiles, setCompletedFiles] = useState(0)
  const [failedFiles, setFailedFiles] = useState(0)
  const [overallProgress, setOverallProgress] = useState(0)
  const [status, setStatus] = useState<string>('processing')
  const [message, setMessage] = useState(`Processing ${totalFiles} files...`)

  const wsRef = useRef<WebSocket | null>(null)
  const pollIntervalRef = useRef<NodeJS.Timeout | null>(null)
  const hasCompletedRef = useRef(false)

  useEffect(() => {
    connectWebSocket()

    return () => {
      if (wsRef.current) {
        wsRef.current.close()
      }
      if (pollIntervalRef.current) {
        clearInterval(pollIntervalRef.current)
      }
    }
  }, [batchId])

  const connectWebSocket = () => {
    const wsBaseUrl = import.meta.env.VITE_WS_BASE_URL || 'ws://localhost:8000'
    const ws = new WebSocket(`${wsBaseUrl}/ws/batch/${batchId}/status`)
    wsRef.current = ws

    let heartbeatInterval: NodeJS.Timeout | null = null

    ws.onopen = () => {
      console.log('Batch WebSocket connected')
      // Send periodic pings to keep connection alive
      heartbeatInterval = setInterval(() => {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({ type: 'ping' }))
        }
      }, 25000)
    }

    ws.onmessage = (event) => {
      const data: BatchWebSocketEvent = JSON.parse(event.data)
      handleWebSocketEvent(data)
    }

    ws.onerror = (error) => {
      console.error('Batch WebSocket error:', error)
      // Start polling fallback
      startPolling()
    }

    ws.onclose = () => {
      if (heartbeatInterval) {
        clearInterval(heartbeatInterval)
      }
      console.log('Batch WebSocket closed')

      // If not yet completed, start polling
      if (!hasCompletedRef.current) {
        startPolling()
      }
    }
  }

  const handleWebSocketEvent = (event: BatchWebSocketEvent) => {
    if (event.type === 'heartbeat' || event.type === 'pong') {
      return
    }

    if (event.type === 'batch_status' || event.type === 'batch_started') {
      // Initial status or batch started
      if (event.total_files) {
        setOverallProgress(event.progress || 0)
      }
      if (event.message) {
        setMessage(event.message)
      }
      if (event.files) {
        // Update file statuses
        setFiles((prev) =>
          prev.map((file) => {
            const update = event.files?.find((f) => f.filename === file.filename)
            if (update) {
              return {
                ...file,
                status: update.status as 'pending' | 'processing' | 'completed' | 'failed',
                content_id: update.content_id,
                error_message: update.error_message,
              }
            }
            return file
          })
        )
      }
    } else if (event.type === 'file_progress') {
      // Update specific file status
      if (event.file_index !== undefined) {
        setFiles((prev) =>
          prev.map((file, idx) => {
            if (idx === event.file_index) {
              return {
                ...file,
                status: event.file_status as 'pending' | 'processing' | 'completed' | 'failed',
                content_id: event.content_id || file.content_id,
                is_duplicate: event.is_duplicate || false,
                error_message: event.error || file.error_message,
              }
            }
            return file
          })
        )
      }

      // Update counters
      if (event.completed_files !== undefined) {
        setCompletedFiles(event.completed_files)
      }
      if (event.failed_files !== undefined) {
        setFailedFiles(event.failed_files)
      }
      if (event.progress !== undefined) {
        setOverallProgress(event.progress)
      }
      if (event.message) {
        setMessage(event.message)
      }
    } else if (event.type === 'batch_completed') {
      // Batch processing complete
      hasCompletedRef.current = true
      setStatus(event.status || 'completed')
      setCompletedFiles(event.completed_files || 0)
      setFailedFiles(event.failed_files || 0)
      setOverallProgress(100)
      setMessage(event.message || 'Batch processing complete')

      // Close WebSocket
      if (wsRef.current) {
        wsRef.current.close()
      }

      // Notify parent
      if (onComplete) {
        onComplete({
          completedFiles: event.completed_files || 0,
          failedFiles: event.failed_files || 0,
          files: files,
        })
      }
    }
  }

  const startPolling = () => {
    if (pollIntervalRef.current) {
      return // Already polling
    }

    let attempts = 0
    const maxAttempts = 300 // 10 minutes (300 * 2s)

    pollIntervalRef.current = setInterval(async () => {
      attempts++

      if (attempts > maxAttempts || hasCompletedRef.current) {
        if (pollIntervalRef.current) {
          clearInterval(pollIntervalRef.current)
        }
        return
      }

      try {
        const batchStatus = await documentsService.getBatchStatus(batchId)

        setCompletedFiles(batchStatus.completed_files)
        setFailedFiles(batchStatus.failed_files)
        setOverallProgress(batchStatus.progress_percentage)
        setStatus(batchStatus.status)

        // Update file statuses
        setFiles(batchStatus.files)

        // Check if completed
        if (
          batchStatus.status === 'completed' ||
          batchStatus.status === 'completed_with_errors'
        ) {
          hasCompletedRef.current = true
          if (pollIntervalRef.current) {
            clearInterval(pollIntervalRef.current)
          }

          setMessage(
            `Batch complete: ${batchStatus.completed_files} succeeded, ${batchStatus.failed_files} failed`
          )

          if (onComplete) {
            onComplete({
              completedFiles: batchStatus.completed_files,
              failedFiles: batchStatus.failed_files,
              files: batchStatus.files,
            })
          }
        } else {
          setMessage(
            `Processing ${batchStatus.completed_files + batchStatus.failed_files}/${batchStatus.total_files} files...`
          )
        }
      } catch (error) {
        console.error('Failed to poll batch status:', error)
      }
    }, 2000)
  }

  const getStatusIcon = (fileStatus: string) => {
    switch (fileStatus) {
      case 'completed':
        return <CheckCircle className="h-4 w-4 text-green-500" />
      case 'failed':
        return <XCircle className="h-4 w-4 text-red-500" />
      case 'processing':
        return <Loader2 className="h-4 w-4 text-blue-500 animate-spin" />
      default:
        return <Clock className="h-4 w-4 text-gray-400" />
    }
  }

  const getStatusBadge = (fileStatus: string, isDuplicate: boolean) => {
    if (isDuplicate) {
      return (
        <Badge variant="secondary" className="text-xs">
          <Copy className="h-3 w-3 mr-1" />
          Duplicate
        </Badge>
      )
    }

    switch (fileStatus) {
      case 'completed':
        return (
          <Badge variant="default" className="bg-green-100 text-green-800 text-xs">
            Completed
          </Badge>
        )
      case 'failed':
        return (
          <Badge variant="destructive" className="text-xs">
            Failed
          </Badge>
        )
      case 'processing':
        return (
          <Badge variant="secondary" className="text-xs">
            Processing
          </Badge>
        )
      default:
        return (
          <Badge variant="outline" className="text-xs">
            Pending
          </Badge>
        )
    }
  }

  return (
    <div className="space-y-4">
      {/* Overall Progress */}
      <div className="space-y-2">
        <div className="flex justify-between text-sm">
          <span className="font-medium">{message}</span>
          <span className="text-muted-foreground">{Math.round(overallProgress)}%</span>
        </div>
        <Progress value={overallProgress} className="h-3" />
        <div className="flex justify-between text-xs text-muted-foreground">
          <span>
            {completedFiles} completed, {failedFiles} failed of {totalFiles} total
          </span>
          {status.includes('completed') && (
            <span className="text-green-600 font-medium">Done!</span>
          )}
        </div>
      </div>

      {/* Warning for failures */}
      {failedFiles > 0 && status.includes('completed') && (
        <Alert className="border-yellow-200 bg-yellow-50">
          <AlertTriangle className="h-4 w-4 text-yellow-600" />
          <AlertDescription className="text-yellow-800">
            {failedFiles} file(s) failed to process. You can retry these files individually.
          </AlertDescription>
        </Alert>
      )}

      {/* File List */}
      <div className="border rounded-lg">
        <div className="p-3 bg-muted/50 border-b flex items-center gap-2">
          <FileText className="h-4 w-4" />
          <span className="font-medium text-sm">Files</span>
        </div>
        <ScrollArea className="h-64">
          <div className="divide-y">
            {files.map((file, index) => (
              <div
                key={index}
                className="p-3 flex items-center justify-between hover:bg-muted/30 transition-colors"
              >
                <div className="flex items-center gap-3 flex-1 min-w-0">
                  {getStatusIcon(file.status)}
                  <div className="min-w-0 flex-1">
                    <p className="text-sm font-medium truncate">{file.filename}</p>
                    {file.error_message && (
                      <p className="text-xs text-red-600 truncate">{file.error_message}</p>
                    )}
                    {file.content_id && file.status === 'completed' && (
                      <p className="text-xs text-muted-foreground">
                        ID: {file.content_id.slice(0, 8)}...
                      </p>
                    )}
                  </div>
                </div>
                <div className="flex-shrink-0">
                  {getStatusBadge(file.status, file.is_duplicate)}
                </div>
              </div>
            ))}
          </div>
        </ScrollArea>
      </div>
    </div>
  )
}

/**
 * BatchResultsModal Component
 * Summary dialog shown when batch upload completes
 */

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../../../components/ui/dialog'
import { Button } from '../../../components/ui/Button'
import { Badge } from '../../../components/ui/Badge'
import { ScrollArea } from '../../../components/ui/scroll-area'
import { Alert, AlertDescription } from '../../../components/ui/alert'
import {
  CheckCircle,
  XCircle,
  Copy,
  RefreshCw,
  ExternalLink,
  PartyPopper,
} from 'lucide-react'
import type { BatchFileStatus } from '../../../api/types'
import { useNavigate } from 'react-router-dom'

interface BatchResultsModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  completedFiles: number
  failedFiles: number
  files: BatchFileStatus[]
  onRetryFailed?: (failedFiles: BatchFileStatus[]) => void
}

export function BatchResultsModal({
  open,
  onOpenChange,
  completedFiles,
  failedFiles,
  files,
  onRetryFailed,
}: BatchResultsModalProps) {
  const navigate = useNavigate()

  const successfulFiles = files.filter((f) => f.status === 'completed')
  const failedFilesList = files.filter((f) => f.status === 'failed')
  const duplicateFiles = files.filter((f) => f.is_duplicate)

  const handleViewLibrary = () => {
    onOpenChange(false)
    navigate('/documents')
  }

  const handleRetryFailed = () => {
    if (onRetryFailed && failedFilesList.length > 0) {
      onRetryFailed(failedFilesList)
    }
  }

  const getResultsMessage = () => {
    if (failedFiles === 0) {
      return 'All documents were uploaded successfully!'
    } else if (completedFiles === 0) {
      return 'All uploads failed. Please check the errors below.'
    } else {
      return `${completedFiles} document(s) uploaded successfully, ${failedFiles} failed.`
    }
  }

  const getResultsVariant = () => {
    if (failedFiles === 0) return 'success'
    if (completedFiles === 0) return 'error'
    return 'warning'
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[600px]">
        <DialogHeader>
          <DialogTitle className="flex items-center gap-2">
            {failedFiles === 0 ? (
              <>
                <PartyPopper className="h-5 w-5 text-green-500" />
                Batch Upload Complete!
              </>
            ) : completedFiles === 0 ? (
              <>
                <XCircle className="h-5 w-5 text-red-500" />
                Upload Failed
              </>
            ) : (
              <>
                <CheckCircle className="h-5 w-5 text-yellow-500" />
                Upload Completed with Issues
              </>
            )}
          </DialogTitle>
          <DialogDescription>{getResultsMessage()}</DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-4">
          {/* Summary Stats */}
          <div className="grid grid-cols-3 gap-4">
            <div className="text-center p-3 bg-green-50 rounded-lg border border-green-200">
              <div className="text-2xl font-bold text-green-600">{completedFiles}</div>
              <div className="text-xs text-green-700">Successful</div>
            </div>
            <div className="text-center p-3 bg-red-50 rounded-lg border border-red-200">
              <div className="text-2xl font-bold text-red-600">{failedFiles}</div>
              <div className="text-xs text-red-700">Failed</div>
            </div>
            <div className="text-center p-3 bg-blue-50 rounded-lg border border-blue-200">
              <div className="text-2xl font-bold text-blue-600">{duplicateFiles.length}</div>
              <div className="text-xs text-blue-700">Duplicates</div>
            </div>
          </div>

          {/* Successful Files */}
          {successfulFiles.length > 0 && (
            <div className="space-y-2">
              <h4 className="text-sm font-medium flex items-center gap-2">
                <CheckCircle className="h-4 w-4 text-green-500" />
                Successfully Uploaded ({successfulFiles.length})
              </h4>
              <ScrollArea className="h-32 border rounded-md">
                <div className="p-2 space-y-1">
                  {successfulFiles.map((file, idx) => (
                    <div
                      key={idx}
                      className="flex items-center justify-between text-sm p-2 hover:bg-muted/50 rounded"
                    >
                      <span className="truncate flex-1">{file.filename}</span>
                      <div className="flex items-center gap-2">
                        {file.is_duplicate && (
                          <Badge variant="secondary" className="text-xs">
                            <Copy className="h-3 w-3 mr-1" />
                            Linked
                          </Badge>
                        )}
                        {file.content_id && (
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-6 px-2"
                            onClick={() => navigate(`/chat/${file.content_id}`)}
                          >
                            <ExternalLink className="h-3 w-3" />
                          </Button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </ScrollArea>
            </div>
          )}

          {/* Failed Files */}
          {failedFilesList.length > 0 && (
            <div className="space-y-2">
              <h4 className="text-sm font-medium flex items-center gap-2">
                <XCircle className="h-4 w-4 text-red-500" />
                Failed ({failedFilesList.length})
              </h4>
              <ScrollArea className="h-32 border border-red-200 rounded-md bg-red-50/50">
                <div className="p-2 space-y-1">
                  {failedFilesList.map((file, idx) => (
                    <div key={idx} className="text-sm p-2">
                      <div className="font-medium truncate">{file.filename}</div>
                      {file.error_message && (
                        <div className="text-xs text-red-600 mt-1">{file.error_message}</div>
                      )}
                    </div>
                  ))}
                </div>
              </ScrollArea>
            </div>
          )}

          {/* Info about duplicates */}
          {duplicateFiles.length > 0 && (
            <Alert className="border-blue-200 bg-blue-50">
              <Copy className="h-4 w-4 text-blue-600" />
              <AlertDescription className="text-blue-800">
                {duplicateFiles.length} file(s) were detected as duplicates and have been linked to
                your account without reprocessing.
              </AlertDescription>
            </Alert>
          )}
        </div>

        <DialogFooter className="flex gap-2">
          {failedFilesList.length > 0 && onRetryFailed && (
            <Button variant="outline" onClick={handleRetryFailed}>
              <RefreshCw className="mr-2 h-4 w-4" />
              Retry Failed ({failedFilesList.length})
            </Button>
          )}
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Close
          </Button>
          <Button onClick={handleViewLibrary}>
            <ExternalLink className="mr-2 h-4 w-4" />
            View Library
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

/**
 * UploadDialog Component
 * Modal dialog for uploading documents (single or bulk)
 */

import { useState, useRef } from 'react'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '../../../components/ui/dialog'
import { Button } from '../../../components/ui/Button'
import { Input } from '../../../components/ui/Input'
import { Label } from '../../../components/ui/label'
import { FileUploader } from '../../../components/ui/FileUploader'
import { Badge } from '../../../components/ui/Badge'
import { Alert, AlertDescription } from '../../../components/ui/alert'
import { Progress } from '../../../components/ui/progress'
import { ScrollArea } from '../../../components/ui/scroll-area'
import {
  Info,
  Upload,
  CheckCircle,
  Loader2,
  FileText,
  X,
  AlertTriangle,
} from 'lucide-react'
import { Document, BatchFileStatus } from '../../../api/types'
import { useAuth } from '../../auth/hooks/useAuth'
import { documentsService } from '../../../api/documents.service'
import { BatchUploadProgress } from './BatchUploadProgress'
import { BatchResultsModal } from './BatchResultsModal'

interface UploadDialogProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  onUploadComplete?: (document: Document) => void
  onBatchComplete?: () => void
}

// Constants matching backend
const MAX_BATCH_FILES = 50
const MAX_FILE_SIZE_MB = 50
const MAX_BATCH_SIZE_MB = 500
const ALLOWED_EXTENSIONS = ['pdf', 'md', 'txt', 'docx', 'doc']

export function UploadDialog({
  open,
  onOpenChange,
  onUploadComplete,
  onBatchComplete,
}: UploadDialogProps) {
  const { user } = useAuth()
  const [files, setFiles] = useState<File[]>([])
  const [title, setTitle] = useState('')
  const [subject, setSubject] = useState('')
  const [tags, setTags] = useState('')
  const [isUploading, setIsUploading] = useState(false)
  const [uploadSuccess, setUploadSuccess] = useState(false)
  const [uploadedDoc, setUploadedDoc] = useState<Document | null>(null)
  const [processingStatus, setProcessingStatus] = useState('')
  const [processingProgress, setProcessingProgress] = useState(0)

  // Batch upload state
  const [isBatchMode, setIsBatchMode] = useState(false)
  const [batchId, setBatchId] = useState<string | null>(null)
  const [batchFiles, setBatchFiles] = useState<
    Array<{ filename: string; size_mb: number; status: string }>
  >([])
  const [showResultsModal, setShowResultsModal] = useState(false)
  const [batchResults, setBatchResults] = useState<{
    completedFiles: number
    failedFiles: number
    files: BatchFileStatus[]
  } | null>(null)
  const [validationError, setValidationError] = useState<string | null>(null)

  const uploadButtonRef = useRef<HTMLButtonElement>(null)

  const handleFilesChange = (newFiles: File[]) => {
    setValidationError(null)

    // Validate files
    if (newFiles.length > MAX_BATCH_FILES) {
      setValidationError(
        `Too many files. Maximum ${MAX_BATCH_FILES} files per batch.`
      )
      return
    }

    // Check file types and sizes
    let totalSize = 0
    for (const file of newFiles) {
      const ext = file.name.split('.').pop()?.toLowerCase() || ''
      if (!ALLOWED_EXTENSIONS.includes(ext)) {
        setValidationError(
          `Invalid file type: ${file.name}. Allowed: ${ALLOWED_EXTENSIONS.join(', ').toUpperCase()}`
        )
        return
      }

      const sizeMB = file.size / (1024 * 1024)
      if (sizeMB > MAX_FILE_SIZE_MB) {
        setValidationError(
          `File too large: ${file.name} (${sizeMB.toFixed(2)}MB). Max: ${MAX_FILE_SIZE_MB}MB`
        )
        return
      }
      totalSize += file.size
    }

    const totalSizeMB = totalSize / (1024 * 1024)
    if (totalSizeMB > MAX_BATCH_SIZE_MB) {
      setValidationError(
        `Total batch size (${totalSizeMB.toFixed(2)}MB) exceeds maximum (${MAX_BATCH_SIZE_MB}MB)`
      )
      return
    }

    setFiles(newFiles)

    // Auto-detect batch mode
    setIsBatchMode(newFiles.length > 1)

    // Auto-fill title from filename if single file and empty
    if (newFiles.length === 1 && !title) {
      const filename = newFiles[0].name.replace(/\.[^/.]+$/, '')
      setTitle(filename)
    } else if (newFiles.length > 1) {
      // Clear single-file title for batch mode
      setTitle('')
    }
  }

  const removeFile = (index: number) => {
    const newFiles = files.filter((_, i) => i !== index)
    setFiles(newFiles)
    setIsBatchMode(newFiles.length > 1)
    setValidationError(null)
  }

  const handleUpload = async () => {
    if (files.length === 0 || !user) return

    // Prevent double-click
    if (uploadButtonRef.current) {
      uploadButtonRef.current.disabled = true
    }

    setIsUploading(true)
    setUploadSuccess(false)
    setValidationError(null)

    if (isBatchMode) {
      await handleBatchUpload()
    } else {
      await handleSingleUpload()
    }
  }

  const handleSingleUpload = async () => {
    setProcessingStatus('Uploading file...')
    setProcessingProgress(0)

    try {
      const file = files[0]
      const apiBaseUrl = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8000'

      if (!user) {
        throw new Error('User not authenticated')
      }

      const formData = new FormData()
      formData.append('file', file)
      formData.append('user_id', user.id)
      formData.append('title', title || file.name)
      if (subject) formData.append('subject', subject)
      if (tags) formData.append('tags', tags)

      const response = await fetch(`${apiBaseUrl}/api/content/upload`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${localStorage.getItem('access_token')}`,
        },
        body: formData,
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        throw new Error(errorData.detail || errorData.message || 'Upload failed')
      }

      const document = await response.json()
      setUploadedDoc(document)

      setProcessingStatus('Upload complete - processing document...')
      setProcessingProgress(10)

      if (!document.is_duplicate) {
        connectWebSocket(document.content_id)
      } else {
        setUploadSuccess(true)
        setProcessingStatus('Duplicate detected - linked to your account')
        setProcessingProgress(100)

        if (onUploadComplete) {
          onUploadComplete(document)
        }

        setTimeout(() => {
          handleClose()
        }, 2000)
      }
    } catch (error: any) {
      console.error('Upload error:', error)
      const errorMessage = error.message || 'Unknown error occurred'
      setProcessingStatus(`Upload failed: ${errorMessage}`)
      setUploadSuccess(false)
      setProcessingProgress(0)
    } finally {
      setIsUploading(false)
      if (uploadButtonRef.current) {
        uploadButtonRef.current.disabled = false
      }
    }
  }

  const handleBatchUpload = async () => {
    setProcessingStatus(`Uploading ${files.length} files...`)
    setProcessingProgress(0)

    try {
      const response = await documentsService.bulkUpload({
        files: files,
        title_prefix: title || undefined,
        subject: subject || undefined,
        tags: tags || undefined,
      })

      setBatchId(response.batch_id)
      setBatchFiles(response.files)
      setProcessingStatus(`Batch started. Processing ${response.total_files} files...`)
      setProcessingProgress(5)

      // The BatchUploadProgress component will handle WebSocket connection
    } catch (error: any) {
      console.error('Batch upload error:', error)
      const errorMessage =
        error.response?.data?.detail || error.message || 'Batch upload failed'
      setProcessingStatus(`Batch upload failed: ${errorMessage}`)
      setIsUploading(false)
      if (uploadButtonRef.current) {
        uploadButtonRef.current.disabled = false
      }
    }
  }

  const handleBatchComplete = (results: {
    completedFiles: number
    failedFiles: number
    files: BatchFileStatus[]
  }) => {
    setBatchResults(results)
    setIsUploading(false)
    setUploadSuccess(true)
    setShowResultsModal(true)

    if (onBatchComplete) {
      onBatchComplete()
    }

    if (uploadButtonRef.current) {
      uploadButtonRef.current.disabled = false
    }
  }

  const connectWebSocket = (contentId: string) => {
    const wsBaseUrl = import.meta.env.VITE_WS_BASE_URL || 'ws://localhost:8000'
    const ws = new WebSocket(`${wsBaseUrl}/ws/document/${contentId}/status`)
    let wsConnected = false
    let pollInterval: NodeJS.Timeout | null = null
    let heartbeatInterval: NodeJS.Timeout | null = null

    ws.onopen = () => {
      wsConnected = true
      heartbeatInterval = setInterval(() => {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({ type: 'ping' }))
        } else {
          if (heartbeatInterval) clearInterval(heartbeatInterval)
        }
      }, 25000)
    }

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data)

      if (data.type === 'heartbeat' || data.type === 'pong') {
        return
      }

      setProcessingStatus(data.message || `Status: ${data.status}`)
      setProcessingProgress(data.progress || 0)

      if (data.status === 'completed') {
        setUploadSuccess(true)
        ws.close()
        if (heartbeatInterval) clearInterval(heartbeatInterval)
        if (pollInterval) clearInterval(pollInterval)

        if (uploadedDoc && onUploadComplete) {
          const completedDoc = { ...uploadedDoc, status: 'completed' as const }
          onUploadComplete(completedDoc)
        }

        setTimeout(() => {
          handleClose()
        }, 2000)
      } else if (data.status === 'failed') {
        setProcessingStatus('Processing failed')
        ws.close()
        if (heartbeatInterval) clearInterval(heartbeatInterval)
        if (pollInterval) clearInterval(pollInterval)
      }
    }

    ws.onerror = (error) => {
      console.error('WebSocket error:', error)
      setProcessingStatus('Connection issue - checking status...')

      if (!pollInterval) {
        startPolling(contentId)
      }
    }

    ws.onclose = () => {
      if (heartbeatInterval) clearInterval(heartbeatInterval)

      if (wsConnected && !uploadSuccess) {
        console.log('WebSocket closed unexpectedly, starting polling')
        if (!pollInterval) {
          startPolling(contentId)
        }
      }
    }

    const startPolling = (contentId: string) => {
      let attempts = 0
      const maxAttempts = 150

      pollInterval = setInterval(async () => {
        attempts++

        if (attempts > maxAttempts) {
          if (pollInterval) clearInterval(pollInterval)
          setProcessingStatus('Processing timeout - please refresh')
          return
        }

        try {
          const doc = await documentsService.getDocument(contentId)

          if (doc.status === 'completed') {
            setUploadSuccess(true)
            setProcessingStatus('Document ready for chat!')
            setProcessingProgress(100)
            if (pollInterval) clearInterval(pollInterval)

            if (uploadedDoc && onUploadComplete) {
              const completedDoc = { ...uploadedDoc, status: 'completed' as const }
              onUploadComplete(completedDoc)
            }

            setTimeout(() => {
              handleClose()
            }, 2000)
          } else if (doc.status === 'failed') {
            setProcessingStatus('Processing failed')
            if (pollInterval) clearInterval(pollInterval)
          } else {
            const progress =
              doc.total_chunks && doc.total_chunks > 0
                ? Math.floor(((doc.processed_chunks || 0) / doc.total_chunks) * 100)
                : 0
            setProcessingProgress(progress)
            setProcessingStatus(
              `Processing... ${doc.processed_chunks || 0}/${doc.total_chunks || 0} chunks`
            )
          }
        } catch (error) {
          console.error('Failed to poll status:', error)
        }
      }, 2000)
    }
  }

  const handleClose = () => {
    if (!isUploading) {
      setFiles([])
      setTitle('')
      setSubject('')
      setTags('')
      setUploadSuccess(false)
      setUploadedDoc(null)
      setProcessingStatus('')
      setProcessingProgress(0)
      setBatchId(null)
      setBatchFiles([])
      setIsBatchMode(false)
      setValidationError(null)
      onOpenChange(false)
    }
  }

  const handleResultsModalClose = () => {
    setShowResultsModal(false)
    handleClose()
  }

  const isFormValid = files.length > 0 && (isBatchMode || title.trim() !== '')
  const totalFileSize = files.reduce((sum, f) => sum + f.size, 0) / (1024 * 1024)

  return (
    <>
      <Dialog open={open} onOpenChange={handleClose}>
        <DialogContent className="sm:max-w-[700px]">
          <DialogHeader>
            <DialogTitle>
              {isBatchMode ? `Bulk Upload (${files.length} files)` : 'Upload Document'}
            </DialogTitle>
            <DialogDescription>
              {isBatchMode
                ? `Upload multiple documents at once. Max ${MAX_BATCH_FILES} files, ${MAX_BATCH_SIZE_MB}MB total.`
                : 'Add a new document to your knowledge base. Supported formats: PDF, TXT, MD, DOCX'}
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-6 py-4">
            {/* File uploader - always show unless batch processing started */}
            {!batchId && (
              <FileUploader
                onFilesChange={handleFilesChange}
                accept=".pdf,.txt,.md,.docx,.doc"
                maxSize={MAX_FILE_SIZE_MB * 1024 * 1024}
                maxFiles={MAX_BATCH_FILES}
                multiple={true}
                disabled={isUploading || uploadSuccess}
              />
            )}

            {/* Validation error */}
            {validationError && (
              <Alert className="border-red-200 bg-red-50">
                <AlertTriangle className="h-4 w-4 text-red-600" />
                <AlertDescription className="text-red-800">
                  {validationError}
                </AlertDescription>
              </Alert>
            )}

            {/* File list for batch mode */}
            {isBatchMode && files.length > 0 && !batchId && (
              <div className="border rounded-lg">
                <div className="p-3 bg-muted/50 border-b flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <FileText className="h-4 w-4" />
                    <span className="font-medium text-sm">
                      Selected Files ({files.length})
                    </span>
                  </div>
                  <Badge variant="outline">{totalFileSize.toFixed(2)} MB total</Badge>
                </div>
                <ScrollArea className="h-40">
                  <div className="divide-y">
                    {files.map((file, index) => (
                      <div
                        key={index}
                        className="p-2 flex items-center justify-between hover:bg-muted/30"
                      >
                        <div className="flex items-center gap-2 min-w-0 flex-1">
                          <FileText className="h-4 w-4 text-muted-foreground flex-shrink-0" />
                          <span className="text-sm truncate">{file.name}</span>
                        </div>
                        <div className="flex items-center gap-2 flex-shrink-0">
                          <span className="text-xs text-muted-foreground">
                            {(file.size / (1024 * 1024)).toFixed(2)} MB
                          </span>
                          {!isUploading && (
                            <Button
                              variant="ghost"
                              size="sm"
                              className="h-6 w-6 p-0"
                              onClick={() => removeFile(index)}
                            >
                              <X className="h-3 w-3" />
                            </Button>
                          )}
                        </div>
                      </div>
                    ))}
                  </div>
                </ScrollArea>
              </div>
            )}

            {/* Batch Upload Progress */}
            {batchId && batchFiles.length > 0 && (
              <BatchUploadProgress
                batchId={batchId}
                totalFiles={files.length}
                initialFiles={batchFiles}
                onComplete={handleBatchComplete}
              />
            )}

            {/* Single file processing status */}
            {!isBatchMode && isUploading && processingStatus && (
              <Alert className="border-blue-200 bg-blue-50">
                <Loader2 className="h-4 w-4 text-blue-600 animate-spin" />
                <AlertDescription className="text-blue-800">
                  <div className="space-y-2">
                    <div>{processingStatus}</div>
                    {processingProgress > 0 && (
                      <Progress value={processingProgress} className="h-2" />
                    )}
                  </div>
                </AlertDescription>
              </Alert>
            )}

            {/* Single file success message */}
            {!isBatchMode && uploadSuccess && uploadedDoc && (
              <Alert className="border-green-200 bg-green-50">
                <CheckCircle className="h-4 w-4 text-green-600" />
                <AlertDescription className="text-green-800">
                  {uploadedDoc.is_duplicate ? (
                    <>
                      Document already exists in knowledge base! Linked to your account.
                      <Badge variant="secondary" className="ml-2">
                        Duplicate Detected
                      </Badge>
                    </>
                  ) : (
                    `Document processed successfully! ${processingProgress}% complete`
                  )}
                </AlertDescription>
              </Alert>
            )}

            {/* Metadata form - show for single file or batch with optional prefix */}
            {!batchId && (
              <div className="grid gap-4">
                {!isBatchMode && (
                  <div className="space-y-2">
                    <Label htmlFor="title">Title *</Label>
                    <Input
                      id="title"
                      placeholder="Document title"
                      value={title}
                      onChange={(e) => setTitle(e.target.value)}
                      disabled={isUploading || uploadSuccess}
                    />
                  </div>
                )}

                {isBatchMode && (
                  <div className="space-y-2">
                    <Label htmlFor="title_prefix">Title Prefix (Optional)</Label>
                    <Input
                      id="title_prefix"
                      placeholder="e.g., Chemistry Unit 3 -"
                      value={title}
                      onChange={(e) => setTitle(e.target.value)}
                      disabled={isUploading || uploadSuccess}
                    />
                    <p className="text-xs text-muted-foreground">
                      If provided, this will be prepended to each filename
                    </p>
                  </div>
                )}

                <div className="space-y-2">
                  <Label htmlFor="subject">Subject</Label>
                  <Input
                    id="subject"
                    placeholder="e.g., Chemistry, Physics, Biology, Mathematics"
                    value={subject}
                    onChange={(e) => setSubject(e.target.value)}
                    disabled={isUploading || uploadSuccess}
                  />
                  <p className="text-xs text-muted-foreground">
                    {isBatchMode
                      ? 'This subject will be applied to all files'
                      : 'Enter the subject area for this document'}
                  </p>
                </div>

                <div className="space-y-2">
                  <Label htmlFor="tags">Tags (comma-separated)</Label>
                  <Input
                    id="tags"
                    placeholder="e.g., stoichiometry, moles, calculations"
                    value={tags}
                    onChange={(e) => setTags(e.target.value)}
                    disabled={isUploading || uploadSuccess}
                  />
                  <p className="text-xs text-muted-foreground">
                    {isBatchMode
                      ? 'These tags will be applied to all files'
                      : 'Add tags to help organize and find your documents'}
                  </p>
                </div>
              </div>
            )}

            {/* Info message */}
            {!uploadSuccess && !isUploading && !batchId && (
              <Alert>
                <Info className="h-4 w-4" />
                <AlertDescription>
                  {isBatchMode ? (
                    <>
                      Documents will be processed concurrently (max 5 at a time) with real-time
                      progress updates. Processing continues even if you navigate away.
                    </>
                  ) : (
                    <>
                      Your document will be processed automatically with real-time status updates.
                      You'll be able to chat with it once processing is complete (usually 1-2
                      minutes).
                    </>
                  )}
                </AlertDescription>
              </Alert>
            )}
          </div>

          <DialogFooter>
            <Button
              variant="outline"
              onClick={handleClose}
              disabled={isUploading && !uploadSuccess}
            >
              {uploadSuccess || batchId ? 'Close' : 'Cancel'}
            </Button>
            {!uploadSuccess && !batchId && (
              <Button
                ref={uploadButtonRef}
                onClick={handleUpload}
                disabled={!isFormValid || isUploading || !!validationError}
              >
                {isUploading ? (
                  <>
                    <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                    {isBatchMode ? 'Starting Upload...' : 'Uploading...'}
                  </>
                ) : (
                  <>
                    <Upload className="mr-2 h-4 w-4" />
                    {isBatchMode
                      ? `Upload All (${files.length} files)`
                      : 'Upload'}
                  </>
                )}
              </Button>
            )}
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Batch Results Modal */}
      {batchResults && (
        <BatchResultsModal
          open={showResultsModal}
          onOpenChange={handleResultsModalClose}
          completedFiles={batchResults.completedFiles}
          failedFiles={batchResults.failedFiles}
          files={batchResults.files}
        />
      )}
    </>
  )
}

